def evolve(state: str, offsets: list[int], t: int) -> str:
    if t == 0:
        return state

    n = len(state)
    mask = (1 << n) - 1
    value = int(state, 2)
    shifts = [d % n for d in offsets]

    # Over XOR, squaring the update doubles every offset.
    while t and value:
        if t & 1:
            result = 0
            for shift in shifts:
                result ^= ((value << shift) & mask) | (value >> (n - shift))
            value = result

        t >>= 1
        shifts = [(2 * shift) % n for shift in shifts]

    return format(value, f"0{n}b")
